import novamind_api as nm

r = nm.query("SELECT day, category, SUM(amount) as amt FROM ledger WHERE day >= 105 AND day <= 112 GROUP BY day, category ORDER BY day, category")
daily = {}
for row in r['rows']:
    d = row['day']
    cat = row['category']
    amt = row['amt']
    if d not in daily:
        daily[d] = {}
    daily[d][cat] = amt

for d in sorted(daily.keys()):
    print(f"Day {d}:")
    tot = 0.0
    for cat, amt in daily[d].items():
        print(f"  {cat}: ${amt:,.2f}")
        tot += amt
    print(f"  Total: ${tot:,.2f}")

