import novamind_api as nm
for day in range(225, 231):
    r = nm.query(f"SELECT category, SUM(amount) as amt FROM ledger WHERE day = {day} GROUP BY category")
    print(f"Day {day}:")
    for row in r["rows"]:
        print(f"  {row['category']}: ${row['amt']:,.2f}")

