import novamind_api as nm
sub_details = nm.query(\"SELECT plan, status, effective_price, billing_day_mod30 FROM subscriptions WHERE status='subscribed'\")
days = {}
for row in sub_details['rows']:
    nbd = row['billing_day_mod30']
    days[nbd] = days.get(nbd, 0) + 1
for k in sorted(days.keys()):
    print(f'billing_day_mod30 {k}: {days[k]}')
"

