./novamind-operation python-c "
import novamind_api as nm
# Write a script to calculate active subs on each day from Day 300 to Day 336
r = nm.query('SELECT start_day, end_day, status FROM subscriptions')
active_by_day = {day: 0 for day in range(300, 337)}
for row in r['rows']:
    start = row['start_day']
    end = row['end_day']
    status = row['status']
    for day in range(300, 337):
        if start <= day:
            if end is None or end > day:
                if status in ['subscribed', 'active']: # wait, what are the active statuses?
                    active_by_day[day] += 1
for day in sorted(active_by_day.keys()):
    print(f'Day {day}: {active_by_day[day]}')
"

